// Weekly App Store ratings report: one Slack message for the last full week (Mon-Sun, UTC).
// Ratings come from the hourly `ratings_snapshots` rows, written reviews from the review sheet.
// Same logic as scripts/ratings_report.py; the README explains the maths.
const COUNTRIES = ['US', 'GB', 'CA', 'AU', 'BR', 'IN'];
const DAY = 24 * 3600 * 1000;
// About a third of Lookup answers come from a stale edge cache (up to ~a day old), so
// the value at a moment is the highest count seen in the 48 h before it.
const WINDOW = 2 * DAY;
const MONTHS = ['Jan', 'Feb', 'Mar', 'Apr', 'May', 'Jun', 'Jul', 'Aug', 'Sep', 'Oct', 'Nov', 'Dec'];

let now = new Date();
try {
  const ts = $('Schedule Trigger').first().json.timestamp;
  if (ts) now = new Date(ts);
} catch (e) {
  // Run without the trigger (e.g. a single node test): use the current time.
}

const today = Date.UTC(now.getUTCFullYear(), now.getUTCMonth(), now.getUTCDate());
const weekEnd = today - ((new Date(today).getUTCDay() + 6) % 7) * DAY; // this Monday 00:00 UTC
const weekStart = weekEnd - 7 * DAY;
const prevStart = weekStart - 7 * DAY;

const num = (v) => Number(String(v ?? '').replace(/,/g, ''));
// Shortest form of the double: Apple's raw answer prints 4.66287 as 4.66286999999...
const decimals = (v) => {
  const s = String(parseFloat(v));
  return s.includes('.') ? s.split('.')[1].length : 0;
};
const parseDate = (v) => {
  if (typeof v === 'number') return Math.round((v - 25569) * DAY); // Sheets serial date
  const t = Date.parse(String(v ?? ''));
  return Number.isNaN(t) ? null : t;
};

const snaps = {};
for (const { json: r } of $('Read snapshots').all()) {
  const at = Date.parse(r.snapshot_at);
  const count = num(r.user_rating_count);
  const avgText = String(r.average_user_rating ?? '').trim();
  const avg = parseFloat(avgText);
  const country = String(r.country ?? '').toUpperCase();
  if (Number.isNaN(at) || !Number.isInteger(count) || Number.isNaN(avg) || !country) continue;
  (snaps[country] ||= []).push({ at, count, avg, d: decimals(avgText) });
}
for (const list of Object.values(snaps)) list.sort((a, b) => a.at - b.at);

const reviews = [];
for (const { json: r } of $('Read reviews').all()) {
  const at = parseDate(r.date);
  const score = Math.round(num(r.score));
  if (at === null || !(score >= 1 && score <= 5)) continue;
  reviews.push({ at, score, country: String(r.country ?? '').toUpperCase() });
}

function valueAt(list, t) {
  let best = null;
  let last = null;
  for (const s of list) {
    if (s.at > t) break;
    last = s;
    if (s.at > t - WINDOW && (!best || s.count >= best.count)) best = s;
  }
  return best || last;
}

function ratingStats(list, start, end) {
  const out = { coveredFrom: start, partial: false };
  let base = valueAt(list, start);
  if (!base) {
    base = list.find((s) => s.at >= start && s.at < end) || null;
    out.partial = true;
    if (base) out.coveredFrom = base.at;
  }
  const last = valueAt(list, end);
  if (end > list[list.length - 1].at) out.partial = true;
  if (!base || !last || !list.some((s) => s.at > start && s.at <= end)) {
    out.noData = true;
    return out;
  }
  out.newRatings = last.count - base.count;
  out.avgEnd = last.avg;
  if (out.newRatings < 0) {
    out.reset = true; // a summary-rating reset or removed ratings
    return out;
  }
  // Integer arithmetic in units of the average's last decimal, so N*A is exact.
  const scale = 10 ** list.reduce((m, s) => Math.max(m, s.d), 0);
  const a1 = Math.round(base.avg * scale);
  const a2 = Math.round(last.avg * scale);
  out.weighted = (last.count * a2 - base.count * a1) / scale; // N2*A2 - N1*A1
  out.errNum = (0.5 * (base.count + last.count)) / scale;
  if (out.newRatings > 0) {
    out.mean = out.weighted / out.newRatings;
    out.err = out.errNum / out.newRatings;
    out.inconsistent = out.mean < 1 - out.err || out.mean > 5 + out.err;
  }
  return out;
}

function reviewStats(country, from, end) {
  const rs = reviews.filter((r) => r.country === country && r.at >= from && r.at < end);
  return { n: rs.length, sum: rs.reduce((s, r) => s + r.score, 0) };
}

function week(start, end) {
  const rows = COUNTRIES.map((country) => {
    const list = snaps[country] || [];
    const r = list.length ? ratingStats(list, start, end) : { coveredFrom: start, noData: true };
    return { country, ...r, reviews: reviewStats(country, r.coveredFrom, end) };
  });
  const total = {
    country: 'All',
    partial: rows.some((r) => r.partial),
    inconsistent: rows.some((r) => r.inconsistent),
    reviews: rows.reduce((t, r) => ({ n: t.n + r.reviews.n, sum: t.sum + r.reviews.sum }), { n: 0, sum: 0 }),
  };
  if (rows.every((r) => r.weighted !== undefined)) {
    total.newRatings = rows.reduce((s, r) => s + r.newRatings, 0);
    if (total.newRatings > 0) {
      total.mean = rows.reduce((s, r) => s + r.weighted, 0) / total.newRatings;
      total.err = rows.reduce((s, r) => s + r.errNum, 0) / total.newRatings;
    }
  } else {
    total.noData = true;
  }
  return [...rows, total];
}

const cur = week(weekStart, weekEnd);
const prev = week(prevStart, weekStart);

const fmtDay = (t) => `${MONTHS[new Date(t).getUTCMonth()]} ${new Date(t).getUTCDate()}`;
const fmtTime = (t) => `${fmtDay(t)} ${new Date(t).toISOString().slice(11, 16)} UTC`;
const thousands = (n) => String(n).replace(/\B(?=(\d{3})+(?!\d))/g, ',');
const ratingsCell = (r) => {
  if (r.noData) return 'no data';
  if (r.reset) return 'reset?';
  return thousands(r.newRatings) + (r.partial ? '†' : '');
};
const meanCell = (r) => {
  if (r.mean === undefined) return '—';
  return `${r.mean.toFixed(2)} ±${r.err.toFixed(2)}` + (r.inconsistent ? '?' : '');
};
// Both metrics use the same completeness gate, including the aggregate row.
function comparePeriods(a, b) {
  const usable = (r) => !r.partial && !r.noData && !r.reset;
  if (!usable(a) || !usable(b)) return { countPercent: null, meanDelta: null };
  return {
    countPercent: a.newRatings === undefined || !(b.newRatings > 0)
      ? null : (a.newRatings - b.newRatings) / b.newRatings * 100,
    meanDelta: a.mean === undefined || b.mean === undefined || a.inconsistent || b.inconsistent
      ? null : a.mean - b.mean,
  };
}
const pct = (p) => {
  if (p === null) return '—';
  const rounded = Math.round(p);
  return `${rounded >= 0 ? '+' : '−'}${Math.abs(rounded)}%`;
};
const diff = (d) => d === null ? '—' : `${d >= 0 ? '+' : '−'}${Math.abs(d).toFixed(2)}`;
const reviewsCell = (r) => (r.reviews.n ? `${r.reviews.n} (${(r.reviews.sum / r.reviews.n).toFixed(1)}★)` : '0');

const header = ['', 'Ratings', 'vs prev', 'Avg★ new', 'vs prev', 'Written'];
const lines = cur.map((r, i) => {
  const p = prev[i];
  const comparison = r.comparison = comparePeriods(r, p);
  return [
    r.country,
    ratingsCell(r),
    pct(comparison.countPercent),
    meanCell(r),
    diff(comparison.meanDelta),
    reviewsCell(r),
  ];
});
const widths = header.map((h, c) => Math.max(h.length, ...lines.map((l) => l[c].length)));
const render = (cells) =>
  cells.map((cell, c) => (c === 0 ? cell.padEnd(widths[c]) : cell.padStart(widths[c]))).join('   ').trimEnd();
const table = [render(header), ...lines.map(render)].join('\n');

const notes = [
  '*Avg★ new*: mean star of the ratings received this week, derived from Apple’s running totals (± is the worst-case rounding error). *Written*: reviews with text, from the review feed (Apple publishes them ~1 day late).',
];
// Storefronts whose collection started mid-week (e.g. newly added ones).
const lateStart = cur.filter((r) => r.country !== 'All' && !r.noData && r.coveredFrom > weekStart);
if (lateStart.length) {
  const from = Math.max(...lateStart.map((r) => r.coveredFrom));
  const who = lateStart.length === COUNTRIES.length ? '' : ` for ${lateStart.map((r) => r.country).join(', ')}`;
  notes.push(`† Partial week${who}: ratings counted from ${fmtTime(from)}, written reviews over the same span.`);
} else if (cur.some((r) => r.partial && !r.noData)) {
  notes.push('† Snapshots stop before the end of the week (collection gap).');
}
if (cur.some((r, i) => r.partial || prev[i].partial)) {
  notes.push('Week-over-week comparisons are omitted whenever either week is partial.');
}
const latest = COUNTRIES.filter((c) => snaps[c]?.length)
  .map((c) => `${c} ${valueAt(snaps[c], weekEnd)?.avg.toFixed(3) ?? '—'}`)
  .join(' · ');
if (latest) notes.push(`All-time average at week end: ${latest}`);

const title = `Speechify iOS · App Store ratings · ${fmtDay(weekStart)} – ${fmtDay(weekEnd - DAY)}`;
const blocks = [
  { type: 'header', text: { type: 'plain_text', text: title, emoji: true } },
  { type: 'section', text: { type: 'mrkdwn', text: '```\n' + table + '\n```' } },
  { type: 'context', elements: [{ type: 'mrkdwn', text: notes.join('\n') }] },
];
const total = cur[cur.length - 1];
const fallback = `${title}: ${total.noData ? 'no data' : `${thousands(total.newRatings)} new ratings, avg ${meanCell(total)}`}`;

return [{ json: { slackBody: { text: fallback, blocks }, report: { weekStart, weekEnd, current: cur, previous: prev } } }];

// Leave disabled until preview, ledger setup and delivery are separately approved.
return [{ json: {
  deliveryEnabled: false,
  channelId: 'REPLACE_WITH_SLACK_CHANNEL_ID',
  appId: '1209815023',
} }];

const settings = $('Delivery settings').first().json;
const report = $input.first().json;
if (settings.deliveryEnabled !== true) return [{ json: { ...report, preview: true } }];
if (!/^[CDG][A-Z0-9]+$/.test(settings.channelId) || !/^\d+$/.test(settings.appId)) {
  throw new Error('Set a concrete Slack channel ID and app ID before delivery');
}
// Never use execution ID as the deduplication key: reruns have different IDs.
const key = [settings.appId, new Date(report.report.weekStart).toISOString(), settings.channelId].join(':');
return [{ json: { ...report, preview: false, key, channelId: settings.channelId,
  owner: String($execution.id), payload: { ...report.slackBody, channel: settings.channelId } } }];

const delivery = $('Prepare claim').first().json;
const rows = $input.all();
if (delivery.preview || rows.length !== 1) return [];
const row = rows[0].json;
// SQLite may return a reread row even for a lost update. Check ownership AND
// revision/content, never merely "the update node returned an item".
if (row.id !== delivery.controlId || row.control_key !== 'weekly-ratings' ||
    row.revision !== delivery.claimedRevision || row.state !== 'sending' ||
    row.owner !== delivery.owner || row.active_key !== delivery.key ||
    row.ledger !== delivery.ledger || row.payload !== delivery.storedPayload) return [];
return [{ json: delivery }];

const delivery = $('Build guarded request').first().json;
const response = $input.first().json;
const body = response.body;
// Only explicit, documented rejections are safe to retry. Unknown/internal errors
// and transport failures may follow a successful post and must remain blocked.
const rejected = new Set(['channel_not_found', 'not_in_channel', 'is_archived',
  'invalid_auth', 'not_authed', 'token_revoked', 'account_inactive',
  'missing_scope', 'no_permission', 'invalid_blocks', 'invalid_arguments',
  'msg_too_long', 'no_text', 'restricted_action', 'rate_limited', 'ratelimited']);
let state = 'ambiguous';
let ts = null;
let detail = 'Unconfirmed send; reconcile before retry';
if (response.statusCode === 200 && body?.ok === true &&
    body.channel === delivery.channelId && typeof body.ts === 'string' && /^\d+\.\d+$/.test(body.ts)) {
  state = 'sent'; ts = body.ts; detail = null;
} else if (response.statusCode >= 200 && response.statusCode < 500 &&
           body?.ok === false && rejected.has(body.error)) {
  state = 'failed'; detail = body.error;
}
return [{ json: { key: delivery.key, owner: delivery.owner, state, ts, detail } }];

const result = $('Prepare persistence').first().json;
const rows = $input.all();
const row = rows[0]?.json;
if (rows.length !== 1 || row?.id !== result.controlId || row.state !== 'idle' ||
    row.revision !== result.completedRevision || row.owner !== result.owner ||
    row.active_key !== result.key || row.ledger !== result.ledger) {
  throw new Error('Delivery result was not persisted by this owner; inspect the control row');
}
if (result.state !== 'sent') throw new Error('Delivery not confirmed; inspect the ledger before retrying');
return [{ json: { key: result.key, state: result.state, ts: result.ts } }];

const delivery = $('Prepare delivery').first().json;
if (delivery.preview) return [];
const rows = $input.all();
const row = rows[0]?.json;
if (rows.length !== 1 || !Number.isSafeInteger(row?.id) || row.control_key !== 'weekly-ratings' ||
    !Number.isSafeInteger(row.revision) || row.revision < 0 || row.revision > Number.MAX_SAFE_INTEGER - 2 ||
    typeof row.ledger !== 'string' || typeof row.owner !== 'string' ||
    typeof row.active_key !== 'string' || typeof row.payload !== 'string' ||
    !['idle', 'sending'].includes(row.state)) {
  throw new Error('Delivery table must contain exactly one valid seeded control row');
}
let ledger;
try { ledger = JSON.parse(row.ledger); } catch { throw new Error('Invalid delivery ledger JSON'); }
if (!ledger || typeof ledger !== 'object' || Array.isArray(ledger)) throw new Error('Invalid delivery ledger');
for (const entry of Object.values(ledger)) {
  if (!entry || !['sending', 'sent', 'failed', 'ambiguous'].includes(entry.state) ||
      typeof entry.owner !== 'string' ||
      (entry.state === 'sent' && (typeof entry.ts !== 'string' || !/^\d+\.\d+$/.test(entry.ts))) ||
      (entry.state !== 'sent' && entry.ts !== null)) {
    throw new Error('Invalid delivery ledger entry; reconcile before sending');
  }
}
// A single existing row avoids racing inserts/upserts. A crash keeps it locked.
if (row.state === 'sending') throw new Error('Delivery is locked by an unfinished attempt; inspect the owner before retrying');
const previous = Object.hasOwn(ledger, delivery.key) ? ledger[delivery.key] : null;
if (previous && previous.state !== 'failed') return [];
ledger[delivery.key] = { state: 'sending', owner: delivery.owner, ts: null, detail: null };
return [{ json: { ...delivery, controlId: row.id, expectedRevision: row.revision,
  claimedRevision: row.revision + 1, ledger: JSON.stringify(ledger),
  storedPayload: JSON.stringify(delivery.payload) } }];

const delivery = $('Build guarded request').first().json;
const result = $input.first().json;
if (result.key !== delivery.key || result.owner !== delivery.owner ||
    !['sent', 'failed', 'ambiguous'].includes(result.state) ||
    (result.state === 'sent' && (typeof result.ts !== 'string' || !/^\d+\.\d+$/.test(result.ts))) ||
    (result.state !== 'sent' && result.ts !== null)) {
  throw new Error('Invalid delivery result; leave control row locked');
}
const ledger = JSON.parse(delivery.ledger);
if (ledger[delivery.key]?.state !== 'sending' || ledger[delivery.key]?.owner !== delivery.owner) {
  throw new Error('Claim/result mismatch; leave control row locked');
}
ledger[delivery.key] = { state: result.state, owner: result.owner, ts: result.ts,
  detail: result.detail, completedAt: new Date().toISOString() };
return [{ json: { ...result, controlId: delivery.controlId,
  claimedRevision: delivery.claimedRevision, completedRevision: delivery.claimedRevision + 1,
  ledger: JSON.stringify(ledger) } }];
